// Standalone correctness island for the fused POLY.3/POLY.4 terminal-empty
// certificate.  The case file is generated by a real KLayout process and
// carries the outcome of:
//
//   enclosing_check(..., Projection).polygons.with_area(0, true)
//
// for both 110 and 140 DBU profiles.  The CUDA result is required to match an
// independently implemented conservative certificate and may report
// TERMINAL_EMPTY only when KLayout's actual terminal region is empty.

#include "poly34_terminal_empty_certificate.cuh"

#include <cuda_runtime.h>

#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

using klayout_cuda::poly34::Box;
using klayout_cuda::poly34::Certificate;

constexpr const char *kCaseMagic = "POLY34CASE1";

struct CaseRecord {
  std::uint64_t poly_begin;
  std::uint64_t active_begin;
  std::uint32_t poly_count;
  std::uint32_t active_count;
  Box gate;
  std::uint8_t actual_poly_empty;
  std::uint8_t actual_active_empty;
  std::uint8_t expected_poly;
  std::uint8_t expected_active;
  std::uint8_t poly_supported;
  std::uint8_t active_supported;
  std::uint8_t reserved[2];
};

struct DeviceResult {
  std::uint8_t poly;
  std::uint8_t active;
  std::uint8_t atomic_empty;
  std::uint8_t reserved;
};

struct LoadedCases {
  std::vector<std::string> names;
  std::vector<CaseRecord> cases;
  std::vector<Box> boxes;
  std::uint64_t deterministic_count = 0;
  std::uint64_t randomized_count = 0;
};

void cuda_require(cudaError_t status, const char *operation) {
  if (status != cudaSuccess) {
    throw std::runtime_error(
        std::string(operation) + ": " + cudaGetErrorString(status));
  }
}

std::uint8_t parse_bit(std::istream &input, const char *field) {
  unsigned int value = 0;
  if (!(input >> value) || value > 1) {
    throw std::runtime_error(std::string("invalid ") + field);
  }
  return static_cast<std::uint8_t>(value);
}

std::uint8_t parse_certificate(std::istream &input, const char *field) {
  unsigned int value = 0;
  if (!(input >> value) ||
      value > static_cast<unsigned int>(Certificate::kTerminalEmpty)) {
    throw std::runtime_error(std::string("invalid ") + field);
  }
  return static_cast<std::uint8_t>(value);
}

Box parse_box(std::istream &input, const char *field) {
  Box box{};
  if (!(input >> box.left >> box.bottom >> box.right >> box.top)) {
    throw std::runtime_error(std::string("invalid ") + field);
  }
  return box;
}

LoadedCases load_cases(const std::string &path) {
  std::ifstream input(path);
  if (!input) {
    throw std::runtime_error("cannot open case file: " + path);
  }
  std::string magic;
  std::uint64_t case_count = 0;
  if (!(input >> magic >> case_count) || magic != kCaseMagic || !case_count ||
      case_count > std::numeric_limits<std::uint32_t>::max()) {
    throw std::runtime_error("invalid POLY34 case header");
  }

  LoadedCases loaded;
  loaded.names.reserve(case_count);
  loaded.cases.reserve(case_count);
  for (std::uint64_t case_id = 0; case_id < case_count; ++case_id) {
    std::string marker;
    std::string name;
    std::string kind;
    CaseRecord record{};
    if (!(input >> marker >> name >> kind) || marker != "CASE" ||
        name.empty() || (kind != "deterministic" && kind != "random")) {
      throw std::runtime_error(
          "invalid case prefix at index " + std::to_string(case_id));
    }
    record.gate = parse_box(input, "gate box");
    record.actual_poly_empty = parse_bit(input, "actual POLY.3 outcome");
    record.actual_active_empty = parse_bit(input, "actual POLY.4 outcome");
    record.expected_poly = parse_certificate(input, "expected POLY.3 certificate");
    record.expected_active = parse_certificate(input, "expected POLY.4 certificate");
    record.poly_supported = parse_bit(input, "POLY.3 support bit");
    record.active_supported = parse_bit(input, "POLY.4 support bit");

    std::uint64_t poly_count = 0;
    if (!(input >> poly_count) ||
        poly_count > std::numeric_limits<std::uint32_t>::max()) {
      throw std::runtime_error("invalid POLY.3 box count");
    }
    record.poly_begin = loaded.boxes.size();
    record.poly_count = static_cast<std::uint32_t>(poly_count);
    for (std::uint64_t i = 0; i < poly_count; ++i) {
      loaded.boxes.push_back(parse_box(input, "POLY.3 primary box"));
    }

    std::uint64_t active_count = 0;
    if (!(input >> active_count) ||
        active_count > std::numeric_limits<std::uint32_t>::max()) {
      throw std::runtime_error("invalid POLY.4 box count");
    }
    record.active_begin = loaded.boxes.size();
    record.active_count = static_cast<std::uint32_t>(active_count);
    for (std::uint64_t i = 0; i < active_count; ++i) {
      loaded.boxes.push_back(parse_box(input, "POLY.4 primary box"));
    }

    loaded.names.push_back(name);
    loaded.cases.push_back(record);
    if (kind == "deterministic") {
      ++loaded.deterministic_count;
    } else {
      ++loaded.randomized_count;
    }
  }
  std::string trailing;
  if (input >> trailing) {
    throw std::runtime_error("trailing content after POLY34 cases");
  }
  return loaded;
}

template <class T>
class DeviceBuffer {
 public:
  explicit DeviceBuffer(std::size_t count) : count_(count) {
    if (count_) {
      cuda_require(
          cudaMalloc(reinterpret_cast<void **>(&pointer_), count_ * sizeof(T)),
          "cudaMalloc");
    }
  }
  ~DeviceBuffer() {
    if (pointer_) {
      cudaFree(pointer_);
    }
  }
  DeviceBuffer(const DeviceBuffer &) = delete;
  DeviceBuffer &operator=(const DeviceBuffer &) = delete;
  T *get() { return pointer_; }
  const T *get() const { return pointer_; }
  std::size_t count() const { return count_; }

 private:
  T *pointer_ = nullptr;
  std::size_t count_ = 0;
};

__global__ void classify_kernel(
    const CaseRecord *cases,
    std::uint32_t case_count,
    const Box *boxes,
    std::uint64_t box_count,
    DeviceResult *results,
    std::uint32_t *status) {
  for (std::uint32_t case_id = blockIdx.x * blockDim.x + threadIdx.x;
       case_id < case_count; case_id += blockDim.x * gridDim.x) {
    const CaseRecord record = cases[case_id];
    if (record.poly_begin > box_count ||
        record.poly_count > box_count - record.poly_begin ||
        record.active_begin > box_count ||
        record.active_count > box_count - record.active_begin) {
      atomicOr(status, 1u);
      continue;
    }
    const Certificate poly = klayout_cuda::poly34::terminal_empty_profile(
        record.gate, boxes + record.poly_begin, record.poly_count,
        klayout_cuda::poly34::kPoly3Distance, record.poly_supported != 0);
    const Certificate active = klayout_cuda::poly34::terminal_empty_profile(
        record.gate, boxes + record.active_begin, record.active_count,
        klayout_cuda::poly34::kPoly4Distance, record.active_supported != 0);
    results[case_id] = {
        static_cast<std::uint8_t>(poly), static_cast<std::uint8_t>(active),
        static_cast<std::uint8_t>(
            poly == Certificate::kTerminalEmpty &&
            active == Certificate::kTerminalEmpty),
        0};
  }
}

const Box *case_boxes(
    const LoadedCases &loaded, std::uint64_t begin, std::uint32_t count) {
  if (begin > loaded.boxes.size() || count > loaded.boxes.size() - begin) {
    throw std::runtime_error("host case box range is invalid");
  }
  return loaded.boxes.data() + begin;
}

int run(const std::string &path) {
  const LoadedCases loaded = load_cases(path);
  std::vector<DeviceResult> expected(loaded.cases.size());
  for (std::size_t i = 0; i < loaded.cases.size(); ++i) {
    const CaseRecord &record = loaded.cases[i];
    const Certificate poly = klayout_cuda::poly34::terminal_empty_profile(
        record.gate,
        case_boxes(loaded, record.poly_begin, record.poly_count),
        record.poly_count, klayout_cuda::poly34::kPoly3Distance,
        record.poly_supported != 0);
    const Certificate active = klayout_cuda::poly34::terminal_empty_profile(
        record.gate,
        case_boxes(loaded, record.active_begin, record.active_count),
        record.active_count, klayout_cuda::poly34::kPoly4Distance,
        record.active_supported != 0);
    expected[i] = {
        static_cast<std::uint8_t>(poly), static_cast<std::uint8_t>(active),
        static_cast<std::uint8_t>(
            poly == Certificate::kTerminalEmpty &&
            active == Certificate::kTerminalEmpty),
        0};
    if (expected[i].poly != record.expected_poly ||
        expected[i].active != record.expected_active) {
      throw std::runtime_error(
          loaded.names[i] + ": host classifier disagrees with independent fixture oracle");
    }
  }

  cuda_require(cudaFree(nullptr), "CUDA initialization");
  DeviceBuffer<CaseRecord> device_cases(loaded.cases.size());
  DeviceBuffer<Box> device_boxes(loaded.boxes.size());
  DeviceBuffer<DeviceResult> device_results(loaded.cases.size());
  DeviceBuffer<std::uint32_t> device_status(1);
  cuda_require(
      cudaMemcpy(
          device_cases.get(), loaded.cases.data(),
          loaded.cases.size() * sizeof(CaseRecord), cudaMemcpyHostToDevice),
      "copy cases to device");
  cuda_require(
      cudaMemcpy(
          device_boxes.get(), loaded.boxes.data(),
          loaded.boxes.size() * sizeof(Box), cudaMemcpyHostToDevice),
      "copy boxes to device");
  cuda_require(
      cudaMemset(device_status.get(), 0, sizeof(std::uint32_t)),
      "clear device status");
  const unsigned int blocks = static_cast<unsigned int>(
      std::min<std::size_t>(65535, (loaded.cases.size() + 127) / 128));
  classify_kernel<<<blocks, 128>>>(
      device_cases.get(), static_cast<std::uint32_t>(loaded.cases.size()),
      device_boxes.get(), loaded.boxes.size(), device_results.get(),
      device_status.get());
  cuda_require(cudaGetLastError(), "launch POLY34 classifier");
  cuda_require(cudaDeviceSynchronize(), "synchronize POLY34 classifier");

  std::vector<DeviceResult> actual(loaded.cases.size());
  std::uint32_t status = 0;
  cuda_require(
      cudaMemcpy(
          actual.data(), device_results.get(),
          actual.size() * sizeof(DeviceResult), cudaMemcpyDeviceToHost),
      "copy POLY34 results to host");
  cuda_require(
      cudaMemcpy(
          &status, device_status.get(), sizeof(status), cudaMemcpyDeviceToHost),
      "copy POLY34 status to host");
  if (status) {
    throw std::runtime_error("device classifier reported invalid input range");
  }

  std::uint64_t terminal_poly = 0;
  std::uint64_t terminal_active = 0;
  std::uint64_t atomic_terminal = 0;
  std::uint64_t false_clean = 0;
  std::uint64_t gpu_mismatch = 0;
  for (std::size_t i = 0; i < loaded.cases.size(); ++i) {
    const CaseRecord &record = loaded.cases[i];
    if (actual[i].poly != expected[i].poly ||
        actual[i].active != expected[i].active ||
        actual[i].atomic_empty != expected[i].atomic_empty) {
      ++gpu_mismatch;
      std::cerr << "GPU_MISMATCH case=" << loaded.names[i] << "\n";
    }
    terminal_poly +=
        actual[i].poly == static_cast<std::uint8_t>(Certificate::kTerminalEmpty);
    terminal_active +=
        actual[i].active == static_cast<std::uint8_t>(Certificate::kTerminalEmpty);
    atomic_terminal += actual[i].atomic_empty != 0;
    const bool unsafe_poly =
        actual[i].poly == static_cast<std::uint8_t>(Certificate::kTerminalEmpty) &&
        !record.actual_poly_empty;
    const bool unsafe_active =
        actual[i].active == static_cast<std::uint8_t>(Certificate::kTerminalEmpty) &&
        !record.actual_active_empty;
    if (unsafe_poly || unsafe_active) {
      ++false_clean;
      std::cerr << "FALSE_CLEAN case=" << loaded.names[i]
                << " poly=" << unsafe_poly << " active=" << unsafe_active << "\n";
    }
    if (i < loaded.deterministic_count) {
      std::cout << "POLY34_CASE name=" << loaded.names[i]
                << " poly="
                << klayout_cuda::poly34::certificate_name(
                       static_cast<Certificate>(actual[i].poly))
                << " active="
                << klayout_cuda::poly34::certificate_name(
                       static_cast<Certificate>(actual[i].active))
                << " atomic_terminal_empty="
                << static_cast<unsigned int>(actual[i].atomic_empty)
                << " klayout_poly_empty="
                << static_cast<unsigned int>(record.actual_poly_empty)
                << " klayout_active_empty="
                << static_cast<unsigned int>(record.actual_active_empty) << "\n";
    }
  }

  std::cout << "POLY34_TERMINAL_EMPTY_ISLAND"
            << " verdict=" << (!gpu_mismatch && !false_clean ? "GO" : "NO_GO")
            << " cases=" << loaded.cases.size()
            << " deterministic=" << loaded.deterministic_count
            << " randomized=" << loaded.randomized_count
            << " gpu_mismatches=" << gpu_mismatch
            << " false_clean=" << false_clean
            << " poly_terminal_empty=" << terminal_poly
            << " active_terminal_empty=" << terminal_active
            << " atomic_terminal_empty=" << atomic_terminal << "\n";
  return !gpu_mismatch && !false_clean ? 0 : 1;
}

}  // namespace

int main(int argc, char **argv) {
  try {
    if (argc != 2) {
      throw std::runtime_error(
          "usage: poly34_terminal_empty_island CASES.poly34");
    }
    return run(argv[1]);
  } catch (const std::exception &error) {
    std::cerr << "POLY34_TERMINAL_EMPTY_ISLAND verdict=NO_GO error=\""
              << error.what() << "\"\n";
    return 2;
  }
}
